-- schema.postgres.sql — la base `cook` traduite de MySQL vers PostgreSQL.
-- Mêmes tables, mêmes colonnes, mêmes clés étrangères que la version MySQL
-- (server/schema.sql). AUTO_INCREMENT devient GENERATED BY DEFAULT AS IDENTITY,
-- float devient double precision, tinyint(1) devient smallint.
--
-- À charger avec :
--   docker exec -i cook-postgres psql -U admin -d cook < server/schema.postgres.sql

CREATE EXTENSION IF NOT EXISTS unaccent;

DROP TABLE IF EXISTS semaines_pref CASCADE;
DROP TABLE IF EXISTS utilisateurs_recettes CASCADE;
DROP TABLE IF EXISTS recettes_semaine CASCADE;
DROP TABLE IF EXISTS recette_outils CASCADE;
DROP TABLE IF EXISTS recettes_ingredients CASCADE;
DROP TABLE IF EXISTS ingredients CASCADE;
DROP TABLE IF EXISTS recettes CASCADE;
DROP TABLE IF EXISTS utilisateurs CASCADE;
DROP TABLE IF EXISTS categories CASCADE;
DROP TABLE IF EXISTS outils CASCADE;
DROP TABLE IF EXISTS timings CASCADE;
DROP TABLE IF EXISTS saisons CASCADE;

CREATE TABLE saisons (
  id   int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nom  varchar(255) DEFAULT NULL
);

CREATE TABLE timings (
  id   int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nom  varchar(255) DEFAULT NULL
);

-- (rayon, unite) identifie une catégorie de la même façon qu'en MySQL :
-- c'est ce duo que le formulaire envoie pour ranger un ingrédient.
CREATE TABLE categories (
  id     int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nom    varchar(255) DEFAULT NULL,
  unite  varchar(10) DEFAULT NULL,
  rayon  varchar(30) DEFAULT NULL
);

CREATE TABLE outils (
  id_outil  int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nom       varchar(20) DEFAULT NULL
);

CREATE TABLE recettes (
  id                  int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nom                 varchar(255) NOT NULL,
  temps_de_preparation int DEFAULT NULL,
  consignes           text,
  image_url           varchar(255) DEFAULT NULL,
  prix                double precision DEFAULT NULL,
  id_saison           int DEFAULT NULL REFERENCES saisons (id),
  -- smallint 0/1/NULL comme le tinyint(1) MySQL, pour garder le code identique
  vegetarien          smallint DEFAULT NULL
);

CREATE TABLE ingredients (
  id            int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nom           varchar(255) DEFAULT NULL,
  glucides      int DEFAULT NULL,
  lipides       int DEFAULT NULL,
  calories      int DEFAULT NULL,
  id_saison     int DEFAULT NULL REFERENCES saisons (id),
  id_categorie  int DEFAULT NULL REFERENCES categories (id),
  proteines     int DEFAULT NULL
);

CREATE TABLE recettes_ingredients (
  id_recette     int NOT NULL REFERENCES recettes (id),
  id_ingredient  int NOT NULL REFERENCES ingredients (id),
  quantite       double precision DEFAULT NULL,
  PRIMARY KEY (id_recette, id_ingredient)
);

CREATE TABLE recette_outils (
  id_outil    int NOT NULL REFERENCES outils (id_outil),
  id_recette  int NOT NULL REFERENCES recettes (id),
  PRIMARY KEY (id_outil, id_recette)
);

CREATE TABLE utilisateurs (
  id         int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nom        varchar(255) DEFAULT NULL,
  prenom     varchar(255) DEFAULT NULL,
  sexe       varchar(255) DEFAULT NULL,
  mail       varchar(255) DEFAULT NULL,
  mdp        varchar(255) DEFAULT NULL,
  activite   varchar(255) DEFAULT NULL,
  objectifs  varchar(255) DEFAULT NULL,
  calories   varchar(255) DEFAULT NULL,
  proteines  varchar(255) DEFAULT NULL,
  lipides    varchar(255) DEFAULT NULL,
  glucides   varchar(255) DEFAULT NULL
);

CREATE TABLE recettes_semaine (
  id_semaine  int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  jour        varchar(20) DEFAULT NULL,
  moment      varchar(20) DEFAULT NULL,
  id_recette  int DEFAULT NULL REFERENCES recettes (id)
);

CREATE TABLE semaines_pref (
  nom         varchar(255) NOT NULL PRIMARY KEY,
  id_user     int DEFAULT NULL REFERENCES utilisateurs (id),
  id_semaine  int DEFAULT NULL REFERENCES recettes_semaine (id_semaine)
);

CREATE TABLE utilisateurs_recettes (
  utilisateur_id  int NOT NULL REFERENCES utilisateurs (id),
  recette_id      int NOT NULL REFERENCES recettes (id),
  PRIMARY KEY (utilisateur_id, recette_id)
);
